  str_n38_11_levelname = "N9 - Penyergapan",
  str_n38_12_levelname = "N10 - Zhui Hu",
  str_n38_13_levelname = "ST3 - Pulang Kampung",
  str_n38_1_levelname_desc = "—",
  str_n38_2_levelname_desc = "Perbaikan Shadowind hampir selesai, tetapi Anda tiba-tiba menjadi korban serangan yang tak terduga. Namun, yang berdiri di antara Anda dan kehancuran pasti adalah...",
  str_n38_3_levelname_desc = "Dengan pesta di atas Shadowind yang sedang berlangsung, Dantang mulai khawatir tentang ketidakhadiran Anda. Dia sama sekali tidak menyadari bahaya yang mengintai di dalam perut kapal...",
  str_n38_4_levelname_desc = "Dengan bantuan Xuan Ji, kamu melanjutkan pencarian asal-usul Clockwork Beasts nakal. Selain dari gudang, tampaknya setiap apotek di kota pelabuhan juga sangat mencurigakan.",
  str_n38_5_levelname_desc = "Setiap orang memiliki alasan mereka sendiri untuk segera kembali ke Longzhou, jadi siapa yang bisa menjadi target sebenarnya dari komplotan jahat ini?",
  str_n38_6_levelname_desc = "—",
  str_n38_7_levelname_desc = "Bahkan di lautan terbuka yang luas, tidak ada jalan untuk menghindari gerombolan Eclipsites, yang disebut sebagai \"roh jahat\" di Longzhou.",
  str_n38_8_levelname_desc = "Pada suatu malam yang berangin kencang dan badai, kilatan petir menghantam Shadowind dan memicu ledakan besar. Di tengah kekacauan, Anda merasakan kehadiran kekuatan khusus...",
  str_n38_9_levelname_desc = "Keesokan paginya, kedamaian akhirnya kembali di kapal, tetapi perairan menjadi sangat asing. Tampaknya kapal menyimpang dari jalur selama cobaan semalam.",
  str_n38_10_levelname_desc = "Bingung, Shadowind tiba di tempat di mana banyak kapal tenggelam di perairan. Untuk melarikan diri dari situasi yang penuh bahaya, Xuan Ji mengorbankan harta karun sekte mereka; namun, bahaya baru mengintai di luar jangkauan pandangan mereka...",
  str_n38_11_levelname_desc = "Serangan mendadak dari perompak dan Clockwork Beasts membuat Anda terkejut, tetapi Xuan Ji dengan cepat menyusun strategi baru. Dia percaya bahwa bahkan Anda dapat memberikan kontribusi besar dalam pertempuran yang akan datang.",
  str_n38_12_levelname_desc = "Saat pertarungan semakin sengit, tampaknya Xuan Ji telah menemukan identitas kapten bajak laut. Orang itu ternyata adalah...",
  str_n38_13_levelname_desc = "—",
  str_n38_1_name_desc_long = "Setelah menerima pekerjaan dari Lin Guild, Anda tiba di Twin Pavilions Bay untuk pertama kalinya dan menyaksikan Shadowind, salah satu kapal dagang besar mereka, tiba di pelabuhan. Mu Yuebai, kapten kapal, mengumumkan bahwa kapal tersebut akan berlabuh selama dua minggu ke depan untuk perbaikan yang sangat dibutuhkan. Untuk itu, Dantang merekomendasikan seorang pengrajin tertentu di Twin Pavilions Bay untuk mengerjakan pekerjaan tersebut.",
  str_n38_2_name_desc_long = "Setelah menghabiskan dua minggu yang produktif di Twin Pavilions Bay, perbaikan Shadowind akhirnya selesai, dan Dantang berhasil meyakinkan utusan dari Lumopolis untuk menghadiri pesta perayaan. Namun, sebelum Anda bisa bergabung dengan mereka, Anda diserang oleh sekelompok Clockwork Beasts ganas yang tiba-tiba muncul di kota. Pada detik-detik terakhir, Xuan Ji muncul dan menyelamatkan Anda dari bahaya—Dia adalah pengrajin yang Dantang sebutkan sebelumnya, serta perancang asli dari binatang mekanik ini.",
  str_n38_3_name_desc_long = "Selama pesta, kabin Shadowind diserbu oleh sejumlah Binatang Jam. Serikat Lin ingin menunda keberangkatan kapal setelah serangan itu, tetapi Dantang khawatir bahwa misinya akan berakhir dengan kegagalan jika dia tidak segera kembali ke Kerajaan Ji. Setelah semua usahanya untuk membujuk Lumopolis mengirim utusan, menunda perjalanan hanya akan mengakibatkan kerugian yang tak terbayangkan.",
  str_n38_4_name_desc_long = "Anda dan Xuan Ji melanjutkan pencarian asal-usul Clockwork Beasts. Saat menyelidiki sebuah apotek, Anda terlibat pertarungan dengan pejuang yang tidak dikenal. Setelah menyadari bahwa kedua belah pihak salah paham, Anda menemukan bahwa lawan Anda adalah Zhong Xu, mantan pejabat Longzhou, dan Liqing, seorang dokter kapal keluarga Lin. Setelah kembali ke Shadowind, Dantang mendesak Anda untuk menggantikan utusan Lumopolis sebagai utusan Astra terbaru ke timur.",
  str_n38_5_name_desc_long = "Anda setuju untuk bepergian ke Longzhou sebagai perwakilan dari Astra, dengan harapan kedua benua tersebut dapat mengamankan masa depan yang lebih baik untuk diri mereka sendiri. Zhong Xu juga mengungkapkan alasan-alasannya ingin segera kembali ke Longzhou, serta alasan-alasan dia diserang. Di bawah tekanan dari begitu banyak orang, Keluarga Lin tidak punya pilihan selain membiarkan Shadowind berangkat sesegera mungkin. Sementara itu, Xuan Ji memulai persiapan sendiri untuk perjalanan panjang yang akan datang.",
  str_n38_6_name_desc_long = "Hari keberangkatan akhirnya tiba, dan semua orang telah membuat persiapan yang cukup untuk pelayaran. Dibekali banyak makanan dan obat-obatan, kapal dan awaknya siap untuk berlayar. Sebelum berangkat, Anda juga mengirim surat perpisahan kepada Vice dan Carleen yang menjelaskan situasi.",
  str_n38_7_name_desc_long = "Di tengah laut lepas, Xuan Ji secara sukarela menawarkan diri untuk menjadi sumber navigasi Shadowind karena armillary sphere Keluarga Lin telah hilang. Selama percakapan Anda dengan dia dan Dantang, Anda banyak belajar tentang Longzhou, navigasi pada umumnya, dan beberapa masalah yang mereka hadapi di Kerajaan Ye. Zhong Xu menyebutkan hal-hal tentang Fiendlings dan Eclipsites di Longzhou, dan itu memberi Anda beberapa perspektif baru.",
  str_n38_8_name_desc_long = "Pada suatu malam yang badai, kilatan petir menyambar langit, menghantam Shadowind dan memicu ledakan di dalam kapal. Ketika semua orang bekerja sama untuk memadamkan api dan memperbaiki kerusakan, Anda menemukan apa yang tampaknya menjadi sumber kebakaran. Namun, tidak lama kemudian, Anda hampir saja tenggelam dalam lautan api.",
  str_n38_9_name_desc_long = "Pada hari kedua, cuaca telah cerah, dan semua api telah dipadamkan. Di bawah pengobatan medis Liqing, Anda segera sadar kembali dan mengingat perasaan ditelan oleh api semalam. Xuan Ji melaporkan bahwa insiden semalam menyebabkan kapal menyimpang dari jalur, dan tak lama kemudian, mereka disergap oleh sekelompok makhluk laut misterius. Shadowind dan awaknya berhasil lolos dengan sempit dan mulai menyelamatkan apa yang bisa mereka lakukan setelah serangan itu.",
  str_n38_10_name_desc_long = "Shadowind tiba di bagian laut yang berbahaya, di mana reruntuhan banyak kapal menghiasi dasar laut. Sebagai upaya terakhir untuk menyelamatkan kapal dan penumpangnya, Xuan Ji memutuskan untuk menggunakan Api Zhuyin, salah satu benda paling berharga dari sekte-nya. Itulah kekuatan yang Anda rasakan tadi malam, dan disebabkan oleh seseorang yang diam-diam melepaskan segelnya. Tiba-tiba, sebuah kapal muncul di kejauhan, tampaknya sebagai respons terhadap sinyal darurat Shadowind. Namun, saat semakin mendekat, Anda menyadari bahwa kapal yang mendekat sebenarnya adalah kapal bajak laut!",
  str_n38_11_name_desc_long = "Sebuah gerombolan bajak laut mulai menyerang awak kapal dengan Clockwork Beasts yang sangat besar, jadi Anda dan Xuan Ji memutuskan untuk berpisah dan menyerang dari sudut yang berbeda. Sementara dia menghalau bajak laut yang menyerang, Anda membebaskan Zhong Xu dan Liqing dari sangkar mekanis yang memenjarakan mereka. Ketika Zhong Xu terjun ke jantung pertempuran, kekuatan tak terhentikannya mengingatkan semua orang tentang masa lalunya sebagai Jenderal Agung Kekaisaran Zhao.",
  str_n38_12_name_desc_long = "Saat memindai titik lemah pada Clockwork Beasts mereka, Xuan Ji membuat penemuan mengejutkan: pemimpin bajak laut adalah Zhui Hu, seorang wanita yang pernah menjadi seniornya dalam studi mereka. Sebagai penemu mesin-mesin kuat ini, dia sejak itu terjatuh ke penyelundupan dan perompakan untuk bertahan hidup. Setelah pertempuran panjang dan sengit, kru Shadowind akhirnya berhasil mengusir bajak laut dan monster mekanis mereka.",
  str_n38_13_name_desc_long = "Shadowind akhirnya mendarat di Longzhou. Dantang menyelesaikan misinya, Zhong Xu dan Liqing akhirnya bersatu kembali dengan Lin Guildmaster, dan Xuan Ji berencana untuk memulai misi baru. Meskipun debu tampaknya telah mengendap, sosok dalam bayangan diam-diam bersiap untuk badai yang akan datang...",
  str_n38_hard_name_1 = "H1 - Dayung Kapal",
  str_n38_hard_name_2 = "H2 - Layar Bayangan",
  str_n38_hard_name_3 = "H3 - Tiang dan Dayung",
  str_n38_hard_name_4 = "H4 - Dayung Terbalik",
  str_n38_hard_desc_1 = "Terumbu karang yang tak bertanda tersembunyi di perairan di depan. Perlambat laju untuk mengidentifikasi rute Anda dengan hati-hati.",
  str_n38_hard_desc_2 = "Angin kencang mulai bertiup di laut. Perketat tali layar dengan cepat untuk menstabilkan kapal.",
  str_n38_hard_desc_3 = "Sebuah gelombang besar sedang menghantam ke arah Anda. Amankan semua fasilitas di geladak dengan cepat.",
  str_n38_hard_desc_4 = "Tebing curam tiba-tiba muncul di dasar laut. Putar balik segera agar Anda tidak menabraknya dan merusak kapal Anda.",
  str_n38_0_levelname_EX = "Kapal Hilang Di Laut (Kapal Karam)",
  str_n38_1_levelname_EX = "EX1 - Gelombang Amarah",
  str_n38_2_levelname_EX = "EX2 - Lautan Badai",
  str_n38_3_levelname_EX = "EX3 - Pasang Gelora",
  str_n38_1_levelname_EX1 = "EX1-1 - Gelombang Dahsyat: Maelstrom",
  str_n38_1_levelname_EX2 = "EX1-2 - Gelombang Dahsyat: Melawan Batu Karang",
  str_n38_2_levelname_EX1 = "EX2-1 - Lautan Badai: Arus Bergelora",
  str_n38_2_levelname_EX2 = "EX2-2 - Lautan Berbadai: Gelombang",
  str_n38_3_levelname_EX1 = "EX3-1 - Pasang Menggelegar: Arus Deras",
  str_n38_3_levelname_EX2 = "EX3-2 - Pasang Mendidih: Air yang Putus Asa",
  str_n38_3_levelname_EX3 = "EX3-3 - Pasang Menggelegar: Tak Terbatas",
